<?php /** 赛事维护表单；负责人王乐之（2411302），AI辅助开发。 */ use yii\helpers\Html;$this->title='编辑赛事数据'; ?><h1><?= $model->isNewRecord?'新增':'编辑' ?> <?= Html::encode($type) ?></h1><?= Html::errorSummary($model) ?><?= Html::beginForm(['edit','type'=>$type,'id'=>$model->id?:0],'post') ?><?php foreach($fields as $name=>$meta):?><div class="form-group"><label for="field-<?= Html::encode($name) ?>"><?= Html::encode($name) ?><?= $meta['required']?' *':'' ?></label><input id="field-<?= Html::encode($name) ?>" name="fields[<?= Html::encode($name) ?>]" value="<?= Html::encode($model->$name??'') ?>" <?= $meta['required']?'required':'' ?>></div><?php endforeach ?><button>保存</button><?= Html::endForm() ?>
